{
  "cvars": {
    "ivs": [
      {
        "description": "Whether the Reader View was activated for the trial (binary treatment). Coded 1 = Reader View ON, 0 = Reader View OFF.",
        "columns": [
          "reader_view"
        ]
      },
      {
        "description": "Binary dyslexia indicator identifying readers with dyslexia (1) vs without (0). Uses the dataset-provided dyslexia_bin column.",
        "columns": [
          "dyslexia_bin"
        ]
      }
    ],
    "dv": {
      "description": "Log-transformed reading speed (natural log of speed in dataset). Log transform reduces skew and models multiplicative effects; primary dependent variable is log_speed.",
      "columns": [
        "log_speed"
      ]
    },
    "controls": [
      {
        "description": "Centered age (years) to control for age-related differences in reading speed. Centered (age - mean(age)) to aid interpretation.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "age_c"
        ]
      },
      {
        "description": "Device used by the reader (categorical). Included as categorical controls (smartphone / tablet / desktop).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "device"
        ]
      },
      {
        "description": "Page identifier (categorical). Controls for page-level differences in content/format.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "page_id"
        ]
      },
      {
        "description": "Binary indicator for whether the reader is a native English speaker (1 = Y, 0 = N).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "english_native_bin"
        ]
      },
      {
        "description": "Centered Flesch-Kincaid readability score (controls text difficulty). Centered (Flesch_Kincaid - mean).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "Flesch_Kincaid_c"
        ]
      },
      {
        "description": "Centered number of words on the page (controls text length). Centered (num_words - mean).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "num_words_c"
        ]
      },
      {
        "description": "Indicator if this trial was a retake (1) or not (0). Controls for practice/retake effects.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "retake_trial"
        ]
      },
      {
        "description": "Unique participant identifier. Used as the grouping variable for a mixed-effects model to account for repeated measures across participants (random intercept).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "uuid"
        ]
      }
    ]
  },
  "transform_code": "def transform(df: pd.DataFrame) -> pd.DataFrame:\n    \"\"\"\n    Transform the raw dataset into a dataframe ready for modeling.\n\n    Steps:\n    - Drop rows missing essential variables (speed, reader_view, dyslexia_bin, uuid).\n    - Ensure types for reader_view, dyslexia_bin, uuid.\n    - Create english_native_bin from english_native (Y -> 1, else 0).\n    - Convert numeric controls to numeric and drop rows with missing control values.\n    - Center continuous controls (age, num_words, Flesch_Kincaid).\n    - Create log_speed = log(speed) as the dependent variable to normalize skew.\n\n    Returns a dataframe containing all columns referenced in the model.\n    \"\"\"\n    df = df.copy()\n\n    # Essential columns for analysis\n    required = ['speed', 'reader_view', 'dyslexia_bin', 'uuid']\n    df = df.dropna(subset=required)\n\n    # Ensure types\n    df['reader_view'] = pd.to_numeric(df['reader_view'], errors='coerce').astype(int)\n    df['dyslexia_bin'] = pd.to_numeric(df['dyslexia_bin'], errors='coerce').astype(int)\n    df['uuid'] = df['uuid'].astype('category')\n\n    # Create english_native_bin: 1 if 'Y', else 0 (handles NaN as 0)\n    df['english_native_bin'] = df['english_native'].fillna('N').astype(str).str.upper().map(lambda x: 1 if x == 'Y' else 0)\n\n    # Convert numeric controls to numeric (coerce errors to NaN) and drop rows missing these controls\n    df['age'] = pd.to_numeric(df['age'], errors='coerce')\n    df['num_words'] = pd.to_numeric(df['num_words'], errors='coerce')\n    df['Flesch_Kincaid'] = pd.to_numeric(df['Flesch_Kincaid'], errors='coerce')\n\n    df = df.dropna(subset=['age', 'num_words', 'Flesch_Kincaid'])\n\n    # Center continuous covariates to improve interpretability\n    df['age_c'] = df['age'] - df['age'].mean()\n    df['num_words_c'] = df['num_words'] - df['num_words'].mean()\n    df['Flesch_Kincaid_c'] = df['Flesch_Kincaid'] - df['Flesch_Kincaid'].mean()\n\n    # Ensure retake_trial is numeric binary\n    if 'retake_trial' in df.columns:\n        df['retake_trial'] = pd.to_numeric(df['retake_trial'], errors='coerce').fillna(0).astype(int)\n    else:\n        df['retake_trial'] = 0\n\n    # Dependent variable: log transform reading speed (natural log). Add small constant if zeros present (not expected here).\n    df['speed'] = pd.to_numeric(df['speed'], errors='coerce')\n    df = df.dropna(subset=['speed'])\n    df['log_speed'] = np.log(df['speed'] + 1e-8)\n\n    # Keep only columns required by the model (but retain original useful columns)\n    keep_cols = [\n        'uuid', 'page_id', 'device', 'reader_view', 'dyslexia_bin',\n        'speed', 'log_speed', 'age', 'age_c', 'num_words', 'num_words_c',\n        'Flesch_Kincaid', 'Flesch_Kincaid_c', 'retake_trial', 'english_native_bin'\n    ]\n    # Some columns (page_id, device) might not exist in certain datasets; ensure they exist\n    for col in ['page_id', 'device']:\n        if col not in df.columns:\n            df[col] = 'missing'\n\n    return df[keep_cols]\n",
  "m_code": "def model(df: pd.DataFrame) -> Any:\n    \"\"\"\n    Fit a mixed-effects model to estimate whether Reader View differentially affects reading speed for readers with dyslexia.\n\n    Model specification:\n    - Dependent variable: log_speed\n    - Fixed effects: reader_view, dyslexia_bin, their interaction, age_c, Flesch_Kincaid_c, num_words_c, retake_trial, english_native_bin, device (categorical), page_id (categorical)\n    - Random effects: random intercept for uuid to account for repeated measures per participant\n\n    Returns the fitted statsmodels results object (MixedLMResults).\n    \"\"\"\n    import statsmodels.formula.api as smf\n\n    # Formula: include interaction between reader_view and dyslexia_bin\n    formula = (\n        'log_speed ~ reader_view * dyslexia_bin + '\n        'age_c + Flesch_Kincaid_c + num_words_c + retake_trial + english_native_bin + '\n        'C(device) + C(page_id)'\n    )\n\n    # Fit mixed-effects model with random intercept per participant (uuid)\n    md = smf.mixedlm(formula, df, groups=df['uuid'], re_formula='1')\n    # Use maximum likelihood (reml=False) for easier comparison if needed\n    mdf = md.fit(reml=False)\n\n    # Print brief summary and return full results object\n    print(mdf.summary())\n    return mdf\n"
}

